Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).

Notation zlen l := (Z.of_nat (length l)).

Definition w4s1_r34_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x6 x7 x8 x9 x11 x12 x13 x14 x15 x17 x18 x19 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH l1 l2 l3 pt3 pt4 PTR3 PTR4 P3 P4 C3 C4o : Z),
    PTR3 = SS + 6 + l1 + l2 + pt3 -> PTR4 = SS + 6 + l1 + l2 + l3 + pt4 ->
    w4s_src_ctx RNG mm SS n SBL SBH -> n < 2^26 ->
    rw_cells asegs mm (P + 152) [C8 (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + 8))] ->
    rw_cells asegs mm (P + 192) [C8 (Z_to_bv 64 (SS + 6 + l1 + l2 + 8))] ->
    rw_cells asegs mm (P + 216) [C8 (Z_to_bv 64 C3)] -> rw_cells asegs mm (P + 240) [C8 (Z_to_bv 64 C4o)] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> KXGoM.apart SS n P 496 ->
    1 <= l1 -> 1 <= l2 -> 1 <= l3 -> 6 + l1 + l2 + l3 + 1 <= n ->
    0 <= pt3 -> (pt3 = 0 \/ pt3 + 8 <= l3) -> 0 <= pt4 -> (pt4 = 0 \/ pt4 + 8 <= n - (6 + l1 + l2 + l3)) ->
    0 <= P3 <= 100 -> 0 <= P4 <= 100 -> (8 <= pt3 -> P3 <= 44) -> (8 <= pt4 -> P4 <= 44) ->
    0 <= bv_unsigned x19 <= 12 -> 0 <= bv_unsigned x15 <= 12 -> 0 <= C3 < 2^64 -> 0 <= C4o < 2^64 ->
    (forall (mm' : amem) (PT3 PT4 ST3 ST4 : Z) (b3w b4w c3' c4w c4' j6 j7 j12 j15 j17 j29 j31 : word),
       munch [(P + 216, P + 224); (P + 240, P + 248)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 216) [C8 c3'] -> rw_cells asegs mm' (P + 240) [C8 c4w] ->
       w4rel l3 (PT3 - (SS + 6 + l1 + l2)) (bv_unsigned b3w) ST3 ->
       w4rel (n - (6 + l1 + l2 + l3)) (PT4 - (SS + 6 + l1 + l2 + l3)) (bv_unsigned b4w) ST4 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp b4w j6 j7 c4' x9 (Z_to_bv 64 PT4) x11 j12 x13 (Z_to_bv 64 ST4) j15
                                 (Z_to_bv 64 ST3) j17 x18 b3w x20 x21 x22 x23 (Z_to_bv 64 PT3) x25 x26 x27 x28 j29 x30 j31)
                            F (Z_to_bv 64 0x9151c) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 P4) x6 x7 x8 x9 (Z_to_bv 64 PTR4) x11 x12 x13 x14 x15
                             (Z_to_bv 64 P3) x17 x18 x19 x20 x21 x22 x23 (Z_to_bv 64 PTR3) x25 x26 x27 x28 x29 x30 x31)
                        F (Z_to_bv 64 0x913d8) fc None mm (seg_rom asegs)).

Ltac w4s34_post K C216 C240 P mm :=
  kx_post_regs_keep;
  let MU := fresh "MU" in let WM := fresh "WM" in
  pose proof (munch_refl [(P + 216, P + 224); (P + 240, P + 248)] mm) as MU;
  pose proof (wmono_refl asegs mm) as WM;
  kx_munch_wins MU [(P + 216, 8); (P + 240, 8)];
  first [kx_cellw C216 | kx_frame C216];
  try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => cbn [cells_size csize]; lia end);
  first [kx_cellw C240 | kx_frame C240];
  try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => cbn [cells_size csize]; lia end);
  kx_post_mem_free;
  lazymatch goal with |- context [mem_denot ?E mm ?l] => let EM := fresh "EM" in remember (mem_denot E mm l) as mm' eqn:EM; clear EM end;
  kxg_hyp C216; kxg_hyp C240;
  kxg_vals;
  kxg_clear;
  eapply K; [ exact MU | exact WM | eassumption | exact C216 | exact C240 | .. ].

Ltac w4s34_rel := unfold w4rel; rewrite ?Z_to_bv_unsigned, ?bv_wrap_small by (unfold bv_modulus; cbn; lia);
  first [ left; split; [reflexivity| lia] | right; split; [reflexivity| lia] ].

